# Initialize an empty to-do list
to_do_list = []

def add_item():
    """Add an item to the to-do list."""
    item = input("Enter an item to add to the to-do list: ").strip()
    if item:
        to_do_list.append(item)
        print(f"To-Do List: [{', '.join(to_do_list)}]")

def remove_item():
    """Remove an item from the to-do list."""
    if to_do_list:
        item_index = int(input("Enter the index of the item to remove (0-based): "))
        if item_index < len(to_do_list):
            del to_do_list[item_index]
            print(f"To-Do List: [{', '.join(to_do_list)}]")
        else:
            print("Item index is out of range.")

def main():
    """Main function to handle user input and commands."""
    while True:
        command = input("Enter 'add' to add an item, 'remove' to remove an item, or 'quit' to exit: ").lower()

        if command == 'add':
            add_item()

        elif command == 'remove':
            remove_item()

        elif command == 'quit':
            print("Goodbye!")
            break

        else:
            print("Invalid command. Please try again.")

if __name__ == "__main__":
    main()
```

This program will keep running until the user types 'quit'. Each time the user enters a command, the corresponding function is called to handle the input.
